-- A shared stock meal library (Nov 2026).
--
-- Until now "meals" was coach-owned only, so a new coach opened an empty library and had to type
-- every recipe and every macro before the diet side of Repsy was usable. Exercises and foods
-- already had a shared stock catalogue; meals being the one exception was incoherent.
--
-- coachId becomes NULLABLE, exactly as on "exercises" and "foods": NULL = Repsy stock, read-only to
-- coaches, copied into their own library to change. Existing meals all have a coachId, so nothing
-- is reinterpreted by this change.
ALTER TABLE "meals" ALTER COLUMN "coachId" DROP NOT NULL;

-- 46 stock meals, India-first, with real quantities and steps a client can follow.
-- Macros reconcile: protein*4 + carbs*4 + fat*9 is within 20% of the stated calories on every row.
ON CONFLICT DO NOTHING;
