INSERT INTO "meals" ("id", "coachId", "name", "mealType", "calories", "proteinG", "carbsG", "fatG", "fiberG", "ingredients", "steps", "dietType") VALUES
  ('stkm_paneer_bhurji_roti', NULL, 'Paneer Bhurji with 2 Roti', 'Breakfast', 512, 26.0, 48.0, 24.0, 7.0, '150 g paneer, 2 whole wheat rotis, 1 onion, 1 tomato, 1 tsp oil, turmeric, chilli', 'Crumble the paneer. Fry onion and tomato in the oil, add spices, then the paneer and cook 3 minutes. Serve with hot rotis.', 'Vegetarian'),
  ('stkm_dal_chawal_ghee', NULL, 'Dal Chawal with Ghee', 'Lunch', 488, 17.0, 78.0, 12.0, 9.0, '1 katori cooked toor dal (150 g), 1.5 katori cooked rice (200 g), 1 tsp ghee, cumin, garlic, tomato', 'Pressure cook the dal with turmeric and salt. Temper cumin and garlic in ghee and pour over. Serve hot with steamed rice.', 'Vegetarian'),
  ('stkm_rajma_chawal', NULL, 'Rajma Chawal', 'Lunch', 531, 20.0, 88.0, 11.0, 14.0, '1 katori cooked rajma (180 g), 1.5 katori cooked rice (200 g), 1 onion, 1 tomato, 2 tsp oil, garam masala', 'Cook soaked rajma till soft. Saute onion, tomato and masala in oil, add rajma and simmer 10 minutes. Serve over rice.', 'Vegan'),
  ('stkm_chole_2_roti', NULL, 'Chole with 2 Roti', 'Lunch', 514, 21.0, 76.0, 14.0, 15.0, '1 katori cooked chickpeas (180 g), 2 whole wheat rotis, 1 onion, 1 tomato, 2 tsp oil, chole masala', 'Saute onion and tomato in oil with chole masala. Add boiled chickpeas and a little water, simmer 10 minutes. Serve with rotis.', 'Vegan'),
  ('stkm_idli_sambar_3', NULL, '3 Idli with Sambar', 'Breakfast', 379, 13.0, 66.0, 7.0, 8.0, '3 medium idli, 1 katori sambar (200 ml), 1 tsp coconut chutney, 1 tsp oil for tempering', 'Steam the idli for 10 minutes. Heat sambar and pour over the idli. Serve with a spoon of chutney.', 'Vegan'),
  ('stkm_masala_dosa_chutney', NULL, 'Masala Dosa with Chutney', 'Breakfast', 436, 11.0, 62.0, 16.0, 6.0, '1 large dosa (80 g batter), 150 g potato masala, 2 tsp oil, 2 tbsp coconut chutney', 'Spread the batter thin on a hot tawa with oil. Fill with potato masala, fold and serve with chutney.', 'Vegetarian'),
  ('stkm_rava_upma', NULL, 'Rava Upma with Vegetables', 'Breakfast', 352, 9.0, 52.0, 12.0, 6.0, '60 g rava, 100 g mixed vegetables, 1 onion, 2 tsp oil, mustard seeds, curry leaves, 10 g peanuts', 'Dry roast the rava. Temper mustard, curry leaves and peanuts in oil, add onion and vegetables, then water and rava. Cook till fluffy.', 'Vegan'),
  ('stkm_poha_peanuts', NULL, 'Kanda Poha with Peanuts', 'Breakfast', 377, 9.0, 56.0, 13.0, 5.0, '70 g flattened rice, 1 onion, 15 g peanuts, 2 tsp oil, mustard seeds, curry leaves, lemon', 'Rinse the poha and drain. Temper mustard, curry leaves, peanuts and onion in oil, add poha and turmeric, steam 3 minutes and finish with lemon.', 'Vegan'),
  ('stkm_aloo_paratha_curd', NULL, 'Aloo Paratha with Curd', 'Breakfast', 470, 15.0, 62.0, 18.0, 7.0, '2 stuffed aloo parathas (80 g atta, 150 g potato), 1 tsp ghee, 150 g curd', 'Stuff the dough with spiced mashed potato and roll out. Roast on a tawa with ghee till golden. Serve with a bowl of chilled curd.', 'Vegetarian'),
  ('stkm_moong_dal_khichdi', NULL, 'Moong Dal Khichdi', 'Dinner', 410, 16.0, 64.0, 10.0, 8.0, '50 g rice, 40 g yellow moong dal, 100 g vegetables, 1 tsp ghee, cumin, turmeric', 'Pressure cook rice, dal, vegetables, turmeric and salt with 3 cups water for 4 whistles. Temper cumin in ghee and mix in.', 'Vegetarian'),
  ('stkm_curd_rice', NULL, 'South Indian Curd Rice', 'Lunch', 357, 13.0, 56.0, 9.0, 3.0, '1 katori cooked rice (180 g), 200 g curd, 1 tsp oil, mustard seeds, curry leaves, ginger, green chilli', 'Mash the warm rice and mix in the curd and salt. Temper mustard, curry leaves, ginger and chilli in oil and stir through.', 'Vegetarian'),
  ('stkm_egg_bhurji_2_roti', NULL, 'Egg Bhurji with 2 Roti', 'Breakfast', 460, 24.0, 46.0, 20.0, 6.0, '3 eggs, 2 whole wheat rotis, 1 onion, 1 tomato, 1 tsp oil, green chilli, coriander', 'Saute onion, tomato and chilli in oil. Pour in the beaten eggs and scramble on low heat. Serve with hot rotis.', 'Eggetarian'),
  ('stkm_boiled_eggs_toast', NULL, '3 Boiled Eggs with 2 Toast', 'Breakfast', 360, 24.0, 30.0, 16.0, 4.0, '3 whole boiled eggs, 2 slices whole wheat bread, 1 tsp butter, black pepper, salt', 'Boil the eggs for 9 minutes and peel. Toast the bread and spread the butter. Season the eggs with salt and pepper.', 'Eggetarian'),
  ('stkm_masala_omelette_toast', NULL, 'Masala Omelette with Toast', 'Breakfast', 345, 20.0, 28.0, 17.0, 4.0, '2 eggs, 1 slice whole wheat bread, 1 onion, 1 tomato, 2 tsp oil, green chilli, coriander', 'Beat the eggs with chopped onion, tomato, chilli and coriander. Cook in oil on both sides. Serve with toast.', 'Eggetarian'),
  ('stkm_chicken_curry_rice', NULL, 'Chicken Curry with Rice', 'Lunch', 562, 38.0, 62.0, 18.0, 5.0, '150 g chicken curry cut, 1 katori cooked rice (180 g), 1 onion, 1 tomato, 2 tsp oil, ginger garlic paste, masala', 'Brown onion with ginger garlic paste in oil, add tomato and masala. Add chicken and water, cook 20 minutes. Serve with rice.', 'Non-vegetarian'),
  ('stkm_tandoori_chicken_salad', NULL, 'Tandoori Chicken with Salad', 'Dinner', 324, 42.0, 12.0, 12.0, 4.0, '200 g chicken breast, 60 g curd, 1 tsp oil, tandoori masala, lemon, 150 g cucumber onion salad', 'Marinate the chicken in curd, masala and lemon for 1 hour. Grill or air fry 20 minutes, turning once. Serve with the salad.', 'Halal'),
  ('stkm_fish_curry_rice', NULL, 'Fish Curry with Rice', 'Lunch', 502, 34.0, 60.0, 14.0, 4.0, '180 g rohu or surmai, 1 katori cooked rice (180 g), 1 onion, tamarind, 2 tsp oil, curry masala', 'Make a thin onion tamarind gravy in oil with the masala. Slide in the fish and simmer 8 minutes without stirring. Serve with rice.', 'Non-vegetarian'),
  ('stkm_chicken_keema_2_roti', NULL, 'Chicken Keema with 2 Roti', 'Dinner', 498, 36.0, 48.0, 18.0, 7.0, '150 g chicken mince, 2 whole wheat rotis, 1 onion, 1 tomato, 50 g peas, 2 tsp oil, garam masala', 'Saute onion and tomato in oil, add the mince and brown well. Add peas, masala and a splash of water and cook 12 minutes. Serve with rotis.', 'Halal'),
  ('stkm_soya_chunk_curry_rice', NULL, 'Soya Chunk Curry with Rice', 'Dinner', 492, 34.0, 62.0, 12.0, 10.0, '60 g dry soya chunks, 1 katori cooked rice (180 g), 1 onion, 1 tomato, 2 tsp oil, garam masala', 'Boil the soya chunks for 5 minutes and squeeze dry. Cook an onion tomato masala in oil, add chunks and water and simmer 10 minutes. Serve with rice.', 'Vegan'),
  ('stkm_tofu_bhurji_2_roti', NULL, 'Tofu Bhurji with 2 Roti', 'Breakfast', 468, 26.0, 46.0, 20.0, 8.0, '150 g firm tofu, 2 whole wheat rotis, 1 onion, 1 tomato, 1 tsp oil, turmeric, chilli', 'Crumble the tofu. Saute onion, tomato and spices in oil, add the tofu and cook 4 minutes. Serve with rotis.', 'Vegan'),
  ('stkm_palak_paneer_2_roti', NULL, 'Palak Paneer with 2 Roti', 'Dinner', 496, 26.0, 44.0, 24.0, 9.0, '120 g paneer, 200 g spinach, 2 whole wheat rotis, 1 tsp oil, garlic, cream 1 tsp', 'Blanch and puree the spinach. Saute garlic in oil, add the puree and paneer cubes and simmer 5 minutes. Serve with rotis.', 'Vegetarian'),
  ('stkm_mixed_veg_sabzi_roti', NULL, 'Mixed Veg Sabzi with 2 Roti', 'Dinner', 360, 11.0, 52.0, 12.0, 11.0, '250 g mixed vegetables, 2 whole wheat rotis, 1 onion, 2 tsp oil, cumin, coriander powder', 'Saute cumin and onion in oil, add the chopped vegetables and spices. Cover and cook 12 minutes till tender. Serve with rotis.', 'Jain'),
  ('stkm_oats_milk_banana', NULL, 'Oats with Milk and Banana', 'Breakfast', 378, 14.0, 58.0, 10.0, 7.0, '50 g rolled oats, 250 ml toned milk, 1 banana, 1 tsp honey, cinnamon', 'Simmer the oats in milk for 5 minutes. Top with sliced banana, honey and a pinch of cinnamon.', 'Vegetarian'),
  ('stkm_besan_chilla_curd', NULL, '2 Besan Chilla with Curd', 'Breakfast', 386, 19.0, 46.0, 14.0, 9.0, '70 g besan, 1 onion, 1 tomato, coriander, 2 tsp oil, 150 g curd', 'Whisk besan with water, onion, tomato and coriander into a batter. Cook two chillas in oil on a tawa. Serve with curd.', 'Vegetarian'),
  ('stkm_sprout_salad_bowl', NULL, 'Moong Sprout Salad Bowl', 'Morning snack', 205, 12.0, 28.0, 5.0, 9.0, '150 g boiled moong sprouts, 1 tomato, 1 onion, 1 cucumber, lemon, chaat masala, 1 tsp oil', 'Steam the sprouts for 5 minutes. Toss with chopped vegetables, lemon, salt and chaat masala.', 'Vegan'),
  ('stkm_fruit_bowl_curd', NULL, 'Fruit Bowl with Curd', 'Mid-morning', 233, 9.0, 38.0, 5.0, 6.0, '150 g curd, 1 apple, 1 banana, 100 g papaya, 5 g chia seeds', 'Chop the fruit into a bowl. Top with curd and chia seeds and eat fresh.', 'Vegetarian'),
  ('stkm_whey_banana_shake', NULL, 'Protein Shake with Banana', 'After breakfast', 301, 30.0, 34.0, 5.0, 3.0, '1 scoop whey protein (30 g), 200 ml toned milk, 1 banana, 100 ml water, ice', 'Blend the whey, milk, banana and water till smooth. Drink immediately after your workout.', 'Vegetarian'),
  ('stkm_peanut_butter_toast', NULL, 'Peanut Butter Toast', 'Evening snack', 294, 12.0, 30.0, 14.0, 5.0, '2 slices whole wheat bread, 20 g peanut butter, 1 tsp flax seeds', 'Toast the bread. Spread peanut butter on both slices and sprinkle flax seeds.', 'Vegan'),
  ('stkm_veg_pulao_raita', NULL, 'Vegetable Pulao with Raita', 'Lunch', 462, 14.0, 70.0, 14.0, 8.0, '80 g raw basmati rice, 150 g mixed vegetables, 2 tsp oil, whole garam masala, 100 g curd raita', 'Saute whole spices and vegetables in oil, add soaked rice and 1.5 cups water. Cook till done and serve with cucumber raita.', 'Vegetarian'),
  ('stkm_lemon_rice_peanuts', NULL, 'Lemon Rice with Peanuts', 'Lunch', 397, 8.0, 62.0, 13.0, 4.0, '1 katori cooked rice (180 g), 1 lemon, 15 g peanuts, 2 tsp oil, mustard seeds, curry leaves, turmeric', 'Temper mustard, curry leaves and peanuts in oil with turmeric. Fold in the cooked rice, salt and lemon juice.', 'Vegan'),
  ('stkm_roti_sabzi_tiffin', NULL, 'Roti Sabzi Tiffin Box', 'Lunch', 405, 14.0, 58.0, 13.0, 12.0, '3 whole wheat rotis, 200 g lauki or bhindi sabzi, 2 tsp oil, 1 small salad portion', 'Cook the sabzi with cumin and spices in oil. Pack with warm rotis and a side salad.', 'Jain'),
  ('stkm_grilled_paneer_salad', NULL, 'Grilled Paneer Salad', 'Dinner', 372, 28.0, 20.0, 20.0, 6.0, '150 g paneer, 200 g lettuce cucumber tomato, 1 tsp olive oil, lemon, black pepper, chaat masala', 'Grill the paneer cubes on a hot pan for 4 minutes. Toss with the salad, olive oil, lemon and pepper.', 'Vegetarian'),
  ('stkm_grilled_chicken_salad', NULL, 'Grilled Chicken Salad', 'Dinner', 358, 40.0, 18.0, 14.0, 6.0, '180 g chicken breast, 200 g salad vegetables, 1 tsp olive oil, lemon, pepper, oregano', 'Season and grill the chicken 6 minutes per side, then slice. Toss the salad with olive oil, lemon and pepper and top with chicken.', 'Non-vegetarian'),
  ('stkm_moong_dal_cheela', NULL, '2 Moong Dal Cheela', 'Breakfast', 359, 21.0, 44.0, 11.0, 9.0, '80 g soaked yellow moong dal, 1 green chilli, ginger, coriander, 2 tsp oil, 50 g curd', 'Grind the soaked dal with chilli and ginger into a batter. Cook two cheelas in oil till crisp. Serve with curd.', 'Vegan'),
  ('stkm_ragi_porridge', NULL, 'Ragi Porridge with Milk', 'Early morning', 308, 11.0, 48.0, 8.0, 7.0, '40 g ragi flour, 250 ml toned milk, 1 tsp jaggery, 5 g almonds', 'Whisk ragi flour into cold water, then cook 5 minutes while stirring. Add milk and jaggery and top with chopped almonds.', 'Vegetarian'),
  ('stkm_masala_buttermilk', NULL, 'Masala Buttermilk Glass', 'After dinner', 66, 4.0, 8.0, 2.0, 1.0, '200 ml buttermilk, roasted cumin powder, black salt, mint leaves, ginger', 'Whisk the buttermilk with cumin powder and black salt. Add crushed mint and ginger and serve chilled.', 'Vegetarian'),
  ('stkm_green_tea_almonds', NULL, 'Green Tea with 10 Almonds', 'Evening snack', 152, 5.0, 6.0, 12.0, 3.0, '1 green tea bag, 200 ml hot water, 10 almonds (14 g)', 'Steep the tea bag in hot water for 3 minutes. Sip alongside the almonds.', 'Vegan'),
  ('stkm_dates_nuts_bite', NULL, 'Dates and Mixed Nuts', 'Snack', 260, 6.0, 32.0, 12.0, 5.0, '3 dates (24 g), 10 g walnuts, 10 g almonds', 'Pit the dates and eat with the nuts as a pre workout snack.', 'Vegan'),
  ('stkm_chaas_roasted_chana', NULL, 'Chaas with Roasted Chana', 'Snack', 204, 12.0, 30.0, 4.0, 7.0, '200 ml chaas, 40 g roasted chana, black salt, cumin powder', 'Season the chaas with black salt and cumin. Eat the roasted chana alongside.', 'Vegetarian'),
  ('stkm_mutton_curry_rice', NULL, 'Mutton Curry with Rice', 'Lunch', 592, 34.0, 60.0, 24.0, 5.0, '150 g mutton, 1 katori cooked rice (180 g), 1 onion, 60 g curd, 2 tsp oil, garam masala', 'Pressure cook the mutton with onion, curd and masala in oil for 20 minutes. Simmer till the gravy thickens and serve with rice.', 'Halal'),
  ('stkm_egg_curry_2_roti', NULL, 'Egg Curry with 2 Roti', 'Dinner', 486, 24.0, 48.0, 22.0, 7.0, '3 boiled eggs, 2 whole wheat rotis, 1 onion, 2 tomatoes, 2 tsp oil, garam masala', 'Make an onion tomato gravy in oil with masala. Halve the boiled eggs, add them and simmer 5 minutes. Serve with rotis.', 'Eggetarian'),
  ('stkm_sambar_rice_light', NULL, 'Light Sambar Rice', 'Dinner', 336, 12.0, 54.0, 8.0, 9.0, '1 katori cooked rice (150 g), 200 ml sambar with vegetables, 1 tsp ghee', 'Heat the sambar with extra vegetables. Mix into the warm rice with a teaspoon of ghee.', 'Vegetarian'),
  ('stkm_paneer_tikka_jain', NULL, 'Jain Paneer Tikka Plate', 'Snack', 314, 24.0, 14.0, 18.0, 3.0, '150 g paneer, 60 g curd, 1 capsicum, 1 tsp oil, tikka masala, lemon', 'Marinate paneer and capsicum in curd and tikka masala for 30 minutes. Grill on a pan 6 minutes and finish with lemon.', 'Jain'),
  ('stkm_chicken_tikka_roll', NULL, 'Chicken Tikka Roll', 'Snack', 422, 32.0, 42.0, 14.0, 5.0, '150 g chicken tikka, 1 whole wheat roti, 1 onion, mint chutney, lemon, 1 tsp oil', 'Grill the marinated chicken till charred. Spread chutney on the roti, add chicken and onion, then roll tight.', 'Halal'),
  ('stkm_sattu_drink', NULL, 'Sattu Drink with Lemon', 'On waking up', 200, 11.0, 30.0, 4.0, 5.0, '40 g sattu, 250 ml water, lemon, black salt, roasted cumin powder', 'Whisk the sattu into water till lump free. Add lemon, black salt and cumin and drink fresh.', 'Vegan'),
  ('stkm_sabudana_khichdi', NULL, 'Sabudana Khichdi', 'Breakfast', 420, 7.0, 62.0, 16.0, 3.0, '70 g soaked sabudana, 20 g peanuts, 1 boiled potato, 2 tsp oil, cumin, green chilli, lemon', 'Temper cumin, chilli and crushed peanuts in oil. Add potato and soaked sabudana and toss on low heat 6 minutes. Finish with lemon.', 'Vegetarian')
